mapper.select:
SELECT account.id AS user_id, account.username, account.name, account.dept_id, account.status


        FROM sys_user_post relation
        INNER JOIN sys_user account ON account.id = relation.user_id AND account.deleted = 0
        WHERE relation.post_id = #{postId}


        FROM sys_user account
        WHERE account.deleted = 0 AND account.status = 0
            AND NOT EXISTS (
                SELECT 1 FROM sys_user_post relation
                WHERE relation.user_id = account.id AND relation.post_id = #{postId}
            )



    AND account.username LIKE CONCAT('%', #{query.username}, '%')


    AND account.name LIKE CONCAT('%', #{query.name}, '%')


    AND account.dept_id = #{query.deptId}


    AND account.status = #{query.status}

ORDER BY account.id
